 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_wrnt_uly_save_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            let rtn = confirm(dts_List.getCellData(dts_List.getRowPosition(), "ISU_ABBRV") + ' 종목에 대한 기초자산명을 저장 하시겠습니까?');
