                // [확인] 버튼이 눌려졌을 경우
                await scwin.wrntUlySave();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05955.btn_wrnt_uly_save_onclick" });
    }
};

/**
 * @method
