 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FinalSave_onclick = async function() {
    try {
        let rtn = confirm('(3단계) 최종 저장 하시겠습니까?');
        if (rtn === 1) {
            // [확인] 버튼이 눌려졌을 경우
            if (scwin.vStep_2 === "N") {
                await $c.win.alert("(2단계) 종목 선정이 저장되지 않았습니다. 종목 선정부터 진행해주세요.");
                return false;
            }
            await scwin.finalSave();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05955.btn_FinalSave_onclick" });
    }
};

