            // if(dts_List.NameString(row, "CHK") == "T" && dts_List.NameString(row, "COND_SATISFACT_YN") == "N"){
            //    alert("해당종목은 1차선정시 로직 1~5번 미충족으로 제외된 종목으로 선정불가 종목입니다.");
