///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setDate
 * @description 조회날짜 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDate = async function() {
    const today = $c.ut.cGetToday("yyyymmdd");
    const fromYear = 2005;
    let toYear = today.substring(0, 4);
    const curQ = Math.ceil(today.substring(4, 6) / 3);
    if (curQ === 1) {
        toYear = toYear - 1;
        cmb_QuarterTp.setValue(4);
    } else {
        cmb_QuarterTp.setValue(curQ - 1);
    }
    let strCbd = "";
    for (i = toYear; i >= fromYear; i--) {
        strCbd = strCbd + (strCbd === "" ? "" : ",") + i + "년^" + i;
    }
    cmb_YearTp.CBData = strCbd;
    cmb_YearTp.setSelectedIndex(0);
    const sbmOptions = {
        id : "sbm_dts_YearQuarter",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_YearQuarter=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&BAS_DATE=" + edt_BDate.getValue();
    url += "&START_DATE=" + edt_SDate.getValue();
    url += "&END_DATE=" + edt_EDate.getValue();
    url += "&REG_EMP_NO=" + js_emp_no;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSyncFinal
 * @description 종목선정후 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSyncFinal = async function() {
    url += "&BAS_DATE=" + edt_BDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ElwListedReceive.do",
