    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name wrntUlySave
 * @description 기초자산명 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.wrntUlySave = async function() {
    if (scwin.wrntUlyCheck()) {
        dts_WrntUly.removeAll();
        // dts_WrntUly.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_WrntUly.insertRow();
        dts_WrntUly.setCellData(1, "WRNT_ULY_NM", txb_WRNT_ULY_NM.getValue());
        dts_WrntUly.setCellData(1, "WRNT_ULY_ENG_NM", txb_WRNT_ULY_ENG_NM.getValue());
        dts_WrntUly.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
        trs_WrntSave.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_WrntSave",
            action : "/ElwListedReceive.do",
            ref : "dts_WrntUly",
            target : "trs_WrntSave=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name isuSelctSave
 * @description 종목선정 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuSelctSave = async function() {
    if (await scwin.IsuCountCheck()) {
        trs_IsuSelctSave.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_IsuSelctSave",
            action : "/ElwListedReceive.do",
            ref : "dts_List",
            target : "trs_IsuSelctSave=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name finalSave
 * @description 최종 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.finalSave = async function() {
    if (await scwin.IsuCountCheck()) {
        dts_final.removeAll();
        // dts_final.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        if (dts_List.getRowCount() > 0) {
            dts_final.setBroadcast(false);
            for (let i = 1; i <= dts_List.getRowCount(); i++) {
                if (dts_List.getCellData(i, "CHK") === "T") {
                    dts_final.insertRow();
                    dts_final.setCellData(dts_final.getRowPosition(), "BAS_YYMM", dts_List.getCellData(i, "BAS_YYMM"));
                    dts_final.setCellData(dts_final.getRowPosition(), "ISU_CD", dts_List.getCellData(i, "ISU_CD"));
                    dts_final.setCellData(dts_final.getRowPosition(), "ISU_KOR_ABBRV", dts_List.getCellData(i, "ISU_ABBRV"));
                    dts_final.setCellData(dts_final.getRowPosition(), "RANK", dts_final.getRowPosition());
                    dts_final.setCellData(dts_final.getRowPosition(), "DYAVG_TRDVAL", dts_List.getCellData(i, "DYAVG_TRDVAL"));
                    dts_final.setCellData(dts_final.getRowPosition(), "MKTCAP", dts_List.getCellData(i, "MKTCAP"));
                }
            }
            dts_final.setBroadcast(true, true);
        }
        trs_IsuSelFinalSave.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_IsuSelFinalSave",
            action : "/ElwListedReceive.do",
            ref : "dts_final",
            target : "trs_IsuSelFinalSave=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setValues
 * @description 기초자산명 display
 * @returns {void}
 * @hidden N
 */
scwin.setValues = function() {
    if (dts_List.getRowCount() > 0) {
        txb_ISUR_CD.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
        txb_COM_NM.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISU_ABBRV"));
        txb_WRNT_ULY_NM.setValue(dts_List.getCellData(dts_List.getRowPosition(), "WRNT_ULY_NM"));
        txb_WRNT_ULY_ENG_NM.setValue(dts_List.getCellData(dts_List.getRowPosition(), "WRNT_ULY_ENG_NM"));
    }
};

/**
 * @method
 * @name notiCount
 * @description 하단 종목 체크수 표시
 * @returns {void}
 * @hidden N
 */
scwin.notiCount = function() {
    let vCnt = 0;
    if (dts_List.getRowCount() > 0) {
        for (let i = 1; i <= dts_List.getRowCount(); i++) {
            if (dts_List.getCellData(i, "CHK") === "T") {
                vCnt = vCnt + 1;
            }
        }
    }
    txb_NotiCount.setValue("현재 " + vCnt + "종목이 선택되어 있습니다.");
};

/**
 * @method
 * @name wrntUlyCheck
 * @description 기초자산명 lengths 체크
 * @returns {void}
 * @hidden N
 */
scwin.wrntUlyCheck = function() {
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_NM, "한글기초자산명")) {
        txb_WRNT_ULY_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_NM, 8, "한글기초자산명")) {
        txb_WRNT_ULY_NM.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_WRNT_ULY_ENG_NM, "영문기초자산명")) {
        txb_WRNT_ULY_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_WRNT_ULY_ENG_NM, 8, "영문기초자산명")) {
        txb_WRNT_ULY_ENG_NM.focus();
        return false;
    }
    return true;
};

// 종목선정(50종목체크)

/**
 * @method
 * @name IsuCountCheck
 * @description Isu Count Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.IsuCountCheck = async function() {
    let vCnt = 0;
    if (dts_List.getRowCount() > 0) {
        for (let i = 1; i <= dts_List.getRowCount(); i++) {
            if (dts_List.getCellData(i, "CHK") === "T") {
                vCnt = vCnt + 1;
            }
        }
    }
    if (vCnt !== 50) {
        await $c.win.alert("50종목만 선택해 주세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name excelDown
 * @description 엑셀 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF05955.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "발행가능KOSPI200 기초자산 선정", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name setYearQuarter
 * @description set Year Quarter 처리
 * @returns {void}
 * @hidden N
 */
scwin.setYearQuarter = function() {
    const baseYq = "" + cmb_YearTp.getValue() + cmb_QuarterTp.getValue();
    edt_SDate.setValue("");
    edt_EDate.setValue("");
    edt_BDate.setValue("");
    for (i = 1; i <= dts_YearQuarter.getRowCount(); i++) {
        if (dts_YearQuarter.getCellData(i, "YYYYQ") === baseYq) {
            edt_SDate.setValue(dts_YearQuarter.getCellData(i, "FROM_DD"));
            edt_EDate.setValue(dts_YearQuarter.getCellData(i, "VALUE"));
            edt_BDate.setValue(dts_YearQuarter.getCellData(i, "VALUE"));
            break;
        }
    }
};

